const SKIN = 'machine-unreachable-other'

/**
 * The skin's own read - the census's sweep.byWhy cell. The verdict
 * book's fifth-heaviest skin's own count - the residual class's own
 * count this word prices across the walks.
 *
 * @param {object|null} [census] walkFailCensus's own image
 * @returns {number} the other skin count (0 when the image cannot
 *   prove the cell - the zero a lawful count)
 */
export function otherOfCensus (census) {
  if (!census || typeof census !== 'object' || Array.isArray(census)) return 0
  const sweep = census.sweep
  if (!sweep || typeof sweep !== 'object' || Array.isArray(sweep)) return 0
  const byWhy = sweep.byWhy
  if (!byWhy || typeof byWhy !== 'object' || Array.isArray(byWhy)) return 0
  if (!Object.prototype.hasOwnProperty.call(byWhy, SKIN)) return 0
  const n = byWhy[SKIN]
  return Number.isInteger(n) && n >= 0 ? n : 0
}

/**
 * The fence - the fold's own image must prove itself before the word
 * rides. A fold that cannot prove itself prices nothing (the fence
 * law: the word never rides a lie). The zero count is lawful (the
 * field's own twenty-two zero faces the proof). The fence never
 * rejects extra keys.
 *
 * @param {object|null} [e] the trend fold:
 *   { back: {other}, prev: {other}, cur: {other} }
 * @returns {boolean}
 */
export function otherTrendConsistent (e) {
  if (!e || typeof e !== 'object' || Array.isArray(e)) return false
  const faceOk = (s) => {
    if (!s || typeof s !== 'object' || Array.isArray(s)) return false
    return Number.isInteger(s.other) && s.other >= 0
  }
  return faceOk(e.back) && faceOk(e.prev) && faceOk(e.cur)
}

